/**
 * Where in the app a request comes from: the `X-Lexpad-Surface` header the
 * server keeps beside every action it records (the activity contract,
 * reports/specs/2026-10-26-activity-tracking.md §2 and §4).
 *
 * Three layers decide it, the first that has a value winning:
 *
 * 1. a surface the call names itself (`RequestOptions.surface`, and the
 *    surface a queued change was made on, which the sync push sends);
 * 2. the innermost overlay that holds one while it is open (`holdSurface`:
 *    the add sheet opened from the tab bar, the paste sheet);
 * 3. the screen the router is on (`surfaceForPath`).
 *
 * Inside the desktop app every name is prefixed `desktop.` (`desktop.app.notebook`),
 * so the desktop window is told apart from the same screen in a browser.
 *
 * Nothing goes out until the server says it takes the headers (`activity` in
 * GET /config, §2.1): until it has, a browser's preflight for a request that
 * carries them would be refused, and every call would fail.
 */
import { isDesktopShell } from './platform/detect.js';

/** The names the front can send (§4 and §4.1); anything else is never sent. */
export const SURFACES = [
  'app.today',
  'app.notebook',
  'app.quick_add',
  'app.word_detail',
  'app.review',
  'app.practice',
  'app.import',
  'app.lex_chat',
  'app.onboarding',
  'app.share_link',
  'app.widget',
  'app.siri',
  'app.paywall',
  'app.settings',
  'app.read',
  'app.ai_cards',
  'app.paste',
  'app.progress',
  'app.auth',
  'app.connect',
  'app.inbox',
  'app.report',
  'app.promo',
  'app.player',
  'app.player.transcript',
  'app.watch',
] as const;

export type Surface = (typeof SURFACES)[number];

const KNOWN: ReadonlySet<string> = new Set(SURFACES);

/** §2's shape for the header. */
const SURFACE_SHAPE = /^[a-z0-9]+(\.[a-z0-9_]+){0,3}$/;
const SURFACE_MAX = 48;
/** §2's shape for the context header: a short slug, never a path or a name. */
const CONTEXT_SHAPE = /^[a-z0-9.-]+$/;
const CONTEXT_MAX = 64;

export const SURFACE_HEADER = 'X-Lexpad-Surface';
export const CONTEXT_HEADER = 'X-Lexpad-Context';
/** The app session the request belongs to, so the server's own events join the visit. */
export const APP_SESSION_HEADER = 'X-Lexpad-App-Session';
const APP_SESSION_SHAPE = /^[A-Za-z0-9_-]{8,64}$/;

/** The activity session (features/activity/events.ts), while the sender runs. */
let appSession: string | undefined;

export function setAppSession(id: string | undefined): void {
  appSession = id !== undefined && APP_SESSION_SHAPE.test(id) ? id : undefined;
}

/**
 * How many requests in a row failed with our headers and were answered
 * without them. One can be a connection that dropped at the wrong moment;
 * `PREFLIGHT_STRIKES` in a row, with no request carrying them getting through
 * between, is a server whose CORS policy does not take them.
 */
export const PREFLIGHT_STRIKES = 2;
let strikes = 0;

/** A request with our headers was refused and answered without them. */
export function notePreflightRefused(): void {
  strikes += 1;
  if (strikes >= PREFLIGHT_STRIKES) {
    strikes = 0;
    setActivityOn(false);
  }
}

/** A request with our headers got through: the server takes them. */
export function notePreflightTaken(): void {
  strikes = 0;
}

/** Whether a request's headers carry anything of ours (to drop them on a refused preflight). */
export function hasActivityHeaders(headers: Record<string, string>): boolean {
  return SURFACE_HEADER in headers || CONTEXT_HEADER in headers || APP_SESSION_HEADER in headers;
}

/** The headers without anything of ours. */
export function withoutActivityHeaders(headers: Record<string, string>): Record<string, string> {
  const {
    [SURFACE_HEADER]: _surface,
    [CONTEXT_HEADER]: _context,
    [APP_SESSION_HEADER]: _session,
    ...rest
  } = headers;
  return rest;
}

let on = false;
let known = false;
let screen: Surface | undefined;
const held: { id: number; surface: Surface }[] = [];
let nextHold = 0;
let entry: { surface: Surface; until: number } | undefined;

/**
 * How long an entry point (the tab bar's add button, a widget) is waited for
 * by the sheet it opens. The navigation in between takes a frame or two; a
 * sheet opened a long while after is the screen's own.
 */
const ENTRY_WAIT_MS = 5_000;

/** The server's `activity` answer (or false when it could not be read); false until then. */
export function setActivityOn(next: boolean): void {
  on = next;
  known = true;
  for (const listener of gateListeners) listener(next);
}

/** Whether the server's answer (or its failure) has come back. */
export function activityKnown(): boolean {
  return known;
}

const gateListeners = new Set<(on: boolean) => void>();

/** Hears every answer of the gate; returns the way to stop. */
export function onActivityGate(listener: (on: boolean) => void): () => void {
  gateListeners.add(listener);
  return () => gateListeners.delete(listener);
}

export function activityOn(): boolean {
  return on;
}

/** The screen the router is on, set by the layout on every navigation. */
export function setScreenSurface(next: Surface | undefined): void {
  if (next === screen) return;
  const before = screen;
  screen = next;
  for (const listener of screenListeners) listener(next, before);
}

const screenListeners = new Set<(next: Surface | undefined, before: Surface | undefined) => void>();

/** Hears each change of screen; returns the way to stop. */
export function onScreenChange(
  listener: (next: Surface | undefined, before: Surface | undefined) => void,
): () => void {
  screenListeners.add(listener);
  return () => screenListeners.delete(listener);
}

/** The short screen name the reports split by (§9 meta.screen). */
export function screenName(surface: Surface): string {
  switch (surface) {
    case 'app.word_detail':
      return 'word';
    case 'app.lex_chat':
      return 'lex';
    case 'app.ai_cards':
      return 'ai';
    default:
      return surface.replace(/^app\./, '').replace(/\./g, '_');
  }
}

/** The screen the router is on now. */
export function screenSurface(): Surface | undefined {
  return screen;
}

/**
 * Holds a surface while an overlay is open; the returned function lets it
 * go. The newest hold wins, so a sheet over a sheet reads as the top one.
 */
export function holdSurface(surface: Surface): () => void {
  const id = (nextHold += 1);
  held.push({ id, surface });
  return () => {
    const at = held.findIndex((h) => h.id === id);
    if (at !== -1) held.splice(at, 1);
  };
}

/**
 * Runs `work` with `surface` held until it settles. Everything the work
 * causes in that time reads as that surface, including a change the learner
 * makes beside it; use it for short background work (a widget's answers).
 */
export async function withSurface<T>(surface: Surface, work: () => Promise<T>): Promise<T> {
  const release = holdSurface(surface);
  try {
    return await work();
  } finally {
    release();
  }
}

/**
 * An entry point names where the next sheet comes from (the tab bar's add
 * button is `app.quick_add`, a home-screen widget `app.widget`); the sheet
 * takes it once as it opens.
 */
export function noteEntry(surface: Surface, now: number = Date.now()): void {
  entry = { surface, until: now + ENTRY_WAIT_MS };
}

/** The entry point waiting for a sheet, taken once; undefined when none is. */
export function takeEntry(now: number = Date.now()): Surface | undefined {
  const waiting = entry;
  entry = undefined;
  return waiting !== undefined && waiting.until >= now ? waiting.surface : undefined;
}

/** Where a request made now comes from, before the desktop prefix. */
export function currentSurface(): Surface | undefined {
  return held[held.length - 1]?.surface ?? screen;
}

/** The name as it goes on the wire: prefixed inside the desktop app, checked against §2. */
export function wireSurface(
  surface: string | undefined,
  desktop: boolean = isDesktopShell(),
): string | undefined {
  if (surface === undefined || !KNOWN.has(surface)) return undefined;
  // The video player exists only in the desktop app; elsewhere its route is a
  // page that says so, and nothing is counted as the player. In the desktop
  // app it is the app's own place, not one of its screens: §4 names it
  // desktop.player (desktop.player.transcript).
  if (!desktop && surface.startsWith('app.player')) return undefined;
  const name = !desktop
    ? surface
    : surface.startsWith('app.player')
      ? surface.replace(/^app\./, 'desktop.')
      : `desktop.${surface}`;
  return name.length <= SURFACE_MAX && SURFACE_SHAPE.test(name) ? name : undefined;
}

/** A context slug as it goes on the wire, or undefined when it is not one. */
export function wireContext(context: string | undefined): string | undefined {
  if (context === undefined) return undefined;
  const slug = context.toLowerCase();
  return slug.length > 0 && slug.length <= CONTEXT_MAX && CONTEXT_SHAPE.test(slug) ? slug : undefined;
}

/**
 * The headers for one request: `surface` is the call's own (null for a call
 * that must carry none, such as a queued change made before surfaces were
 * recorded), undefined for "where the learner is now". Empty while the server
 * has not said it takes them.
 */
export function surfaceHeaders(surface?: string | null, context?: string): Record<string, string> {
  if (!on) return {};
  const out: Record<string, string> = {};
  if (appSession !== undefined) out[APP_SESSION_HEADER] = appSession;
  if (surface === null) return out;
  const name = wireSurface(surface ?? currentSurface());
  if (name !== undefined) out[SURFACE_HEADER] = name;
  const slug = wireContext(context);
  if (slug !== undefined) out[CONTEXT_HEADER] = slug;
  return out;
}

/**
 * The screen a path is (the routes in app/routes.tsx). Paths the learner does
 * nothing on that the server records (a 404) give undefined.
 */
export function surfaceForPath(pathname: string): Surface | undefined {
  const path = pathname.replace(/\/+$/, '') || '/';
  const first = path.split('/')[1] ?? '';
  switch (first) {
    case '':
      return 'app.today';
    case 'notebook':
      return 'app.notebook';
    case 'words':
      return 'app.word_detail';
    case 'session':
      return 'app.review';
    case 'games':
    case 'practice':
    case 'decks':
      return 'app.practice';
    case 'assistant':
      return 'app.lex_chat';
    case 'ai':
      return 'app.ai_cards';
    case 'read':
      return 'app.read';
    case 'progress':
      return 'app.progress';
    case 'settings':
      // Import lives in Settings → Data; the rest of Settings is settings.
      return path.startsWith('/settings/data') ? 'app.import' : 'app.settings';
    case 'welcome':
    case 'intro':
      return 'app.onboarding';
    case 's':
      return 'app.share_link';
    case 'auth':
    case 'verify':
    case 'forgot':
    case 'reset-password':
      return 'app.auth';
    case 'connect':
    case 'connect-extension':
    case 'connect-desktop':
      return 'app.connect';
    case 'forms':
    case 'notifications':
      return 'app.inbox';
    case 'report-ai':
      return 'app.report';
    case 'promo':
      return 'app.promo';
    case 'player':
      return 'app.player';
    case 'watch':
      return 'app.watch';
    default:
      return undefined;
  }
}

/* ----------------------------------------------------- client events */

/**
 * The client events the front sends (§3 client-only and §9), each with the
 * meta keys it may carry: exactly the server's allow-list (the spec's API
 * section, "Client → server"); a key it does not list would be dropped there. Counts and durations only: never a word, a query,
 * a file name, an address or a title.
 */
export const ACTIVITY_EVENTS = {
  'app.open': ['cold', 'startMs'],
  'app.background': [],
  'screen.time': ['screen', 'seconds'],
  'notebook.browse': ['seconds', 'wordsSeen', 'wordsOpened', 'audioPlayed', 'searches', 'searchesEmpty'],
  'paywall.view': ['trigger', 'place'],
  'paywall.dismiss': ['trigger', 'place'],
  'share.open': [],
  'push.permission': ['state'],
  'push.open': ['kind'],
  'reminder.set': ['bucket'],
  'settings.change': ['key'],
  'client.error': ['kind', 'screen'],
  'sync.offline_ops': ['ops'],
  'client.latency': ['route', 'ms'],
  'player.open': ['mode', 'nSubs', 'container', 'codec', 'hasSubs'],
  'player.watch': ['minutes'],
  'player.error': ['stage', 'codec'],
  'player.sub_offset': ['changes'],
  'player.sub_fix_encoding': [],
  'player.next_episode': [],
  // The store's rating dialog in the phone apps (features/review): asked, or held and why.
  'review.ask': ['kind'],
  'review.held': ['reason', 'kind'],
} as const satisfies Record<string, readonly string[]>;

export type ActivityName = keyof typeof ACTIVITY_EVENTS;
export type ActivityMeta = Record<string, string | number | boolean>;

export interface ActivityEvent {
  name: ActivityName;
  /** How many: minutes, items, a count (1..1000 on the server). */
  n?: number;
  /** A surface of the event's own; undefined is where the learner is now. */
  surface?: Surface;
  context?: string;
  meta?: ActivityMeta;
}

/** What the sender keeps: the event with its time and the surface already decided. */
export interface QueuedEvent {
  /** UUID v4 from this device; the server counts an id once however often it lands (§10). */
  eventId: string;
  name: ActivityName;
  at: string;
  n?: number;
  surface?: string;
  context?: string;
  meta?: ActivityMeta;
}

/** The sender (features/activity), once the app has started it. */
let sink: ((event: QueuedEvent) => void) | undefined;
/** Events from before the sender started, at most `EARLY_MAX`. */
const early: QueuedEvent[] = [];
const EARLY_MAX = 100;

/** Meta trimmed to the keys the event may carry, and to short plain values. */
function cleanMeta(name: ActivityName, meta: ActivityMeta | undefined): ActivityMeta | undefined {
  if (meta === undefined) return undefined;
  const allowed: readonly string[] = ACTIVITY_EVENTS[name];
  const out: ActivityMeta = {};
  for (const key of allowed) {
    const value = meta[key];
    if (typeof value === 'boolean' || (typeof value === 'number' && Number.isFinite(value))) out[key] = value;
    else if (typeof value === 'string' && /^[a-z0-9_.-]{1,32}$/i.test(value)) out[key] = value;
  }
  return Object.keys(out).length === 0 ? undefined : out;
}

/**
 * Notes one client event. Fire and forget, and never a request of its own:
 * the sender batches them and sends every few minutes and as the app goes
 * to the background. Nothing leaves while the server has not said `activity`.
 * Safe to call from anywhere, at any rate a screen's own work runs at; never
 * per frame or per scroll.
 */
export function signal(event: ActivityEvent, now: number = Date.now()): void {
  if (known && !on) return;
  const queued = eventFor(event, now);
  if (sink !== undefined) {
    sink(queued);
    return;
  }
  early.push(queued);
  if (early.length > EARLY_MAX) early.shift();
}

/** The event as it is kept and sent: its id, time, wire surface and checked meta. */
export function eventFor(event: ActivityEvent, now: number = Date.now()): QueuedEvent {
  const surface = wireSurface(event.surface ?? currentSurface());
  const context = wireContext(event.context);
  const where = event.surface ?? currentSurface();
  // An error says on which screen it happened (the server keeps `screen`).
  const given =
    event.name === 'client.error' && event.meta?.screen === undefined && where !== undefined
      ? { ...event.meta, screen: screenName(where) }
      : event.meta;
  const meta = cleanMeta(event.name, given);
  const queued: QueuedEvent = {
    eventId: crypto.randomUUID(),
    name: event.name,
    at: new Date(now).toISOString(),
    ...(event.n === undefined ? {} : { n: Math.max(1, Math.min(1000, Math.round(event.n))) }),
    ...(surface === undefined ? {} : { surface }),
    ...(context === undefined ? {} : { context }),
    ...(meta === undefined ? {} : { meta }),
  };
  return queued;
}

/** The sender takes over; whatever was noted before it is handed to it at once. */
/**
 * How old an event noted before sign-in may be and still go with the account
 * that signs in (owner, 26 Oct 2026; spec §10 Identity: the last 24 h only).
 */
export const ANONYMOUS_MAX_AGE_MS = 24 * 60 * 60 * 1000;
/** How far ahead of the clock an event's time may be (a clock corrected a little). */
export const CLOCK_SKEW_MS = 5 * 60 * 1000;

/**
 * Whether an event noted before sign-in may go with the account signing in
 * now: noted in the last 24 hours. One dated ahead of the clock by more than
 * `CLOCK_SKEW_MS` (the clock was put back) has an age nobody can tell, and is
 * dropped; so is an older one.
 */
export function mayAttach(event: QueuedEvent, now: number = Date.now()): boolean {
  const at = Date.parse(event.at);
  if (Number.isNaN(at) || at > now + CLOCK_SKEW_MS) return false;
  return now - at <= ANONYMOUS_MAX_AGE_MS;
}

export function setActivitySink(
  next: ((event: QueuedEvent) => void) | undefined,
  now: number = Date.now(),
): void {
  sink = next;
  const waiting = early.splice(0);
  // The sender stopping (sign-out) starts the early list from nothing: what
  // is noted after it is a signed-out visit's, never the last account's.
  if (next === undefined) return;
  for (const event of waiting) if (mayAttach(event, now)) next(event);
}

/** For tests: back to a fresh start. */
export function __resetSurfaceForTests(): void {
  on = false;
  known = false;
  sink = undefined;
  appSession = undefined;
  strikes = 0;
  early.length = 0;
  gateListeners.clear();
  screenListeners.clear();
  screen = undefined;
  held.length = 0;
  entry = undefined;
}
